55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type InsurableItemType = keyof typeof BASE_PREMIUMS;
69	
70	const isInsurableItemType = (type: string): type is InsurableItemType =>
71	  type in BASE_PREMIUMS;
72	
73	// Unknown item types are not yet rejected — the spec requires an error, but no
74	// test drives that behaviour yet, so they are priced at 0 for the moment.
75	const UNPRICED_UNKNOWN_TYPE = 0;
76	
77	const basePremiumForItem = (item: Item): number =>
78	  isInsurableItemType(item.type)
79	    ? BASE_PREMIUMS[item.type]
80	    : UNPRICED_UNKNOWN_TYPE;
81	
82	const BLOCK_SIZE = 3;
83	
84	const BLOCK_BASE_PREMIUM = 60;
85	
86	const isBlock = (items: Item[]): boolean =>
87	  items.length === BLOCK_SIZE &&
88	  items.every((item) => item.type === items[0].type);
89	
90	const basePremiumForItems = (items: Item[]): number =>
91	  isBlock(items)
92	    ? BLOCK_BASE_PREMIUM
93	    : items.reduce((sum, item) => sum + basePremiumForItem(item), 0);
94	
95	const withInitialAssessmentSurcharge = (basePremium: number): number =>
96	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
97	
98	const quotePremium = (items: Item[]): number =>
99	  Math.round(
100	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
101	  );
102	
103	const runStep = (step: Step): StepResult => {
104	  if (step.op === "quote") return { premium: quotePremium(step.items) };
105	  throw new Error(`Unsupported step: ${step.op}`);
106	};
107	
108	export const runScenario = (scenario: Scenario): ScenarioResult => ({
109	  results: scenario.steps.map(runStep),
110	});
