const areAllAlike = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0].type);

// The block rule is currently evaluated over the whole item list. Grouping by
// type comes with the pending 3-runes-plus-3-moonstones test.
const isBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && areAllAlike(items);
